235:     public getAuthorizationUrl() {
236:         this.params = this.environment;
237:         if (!this.params.hasOwnProperty('nonce')) {
238:             const nonceData = this.generateState();
239:             this.params = { ...this.params, ...{ nonce: nonceData } };
240:         }
241:         if (!this.params.state) {
242:             this.params.state = this.generateState();
243:         }
244:         let url = this.params.AUTORIZATION_URL + '?' +
245:             'client_id=' + encodeURIComponent(this.params.CLIENTE_ID) + '&' +
246:             'redirect_uri=' + encodeURIComponent(this.params.REDIRECT_URL) + '&' + // + window.location.href + '&' para redirect con regex
247:             'response_type=' + encodeURIComponent(this.params.RESPONSE_TYPE) + '&' +
248:             'scope=' + encodeURIComponent(this.params.SCOPE) + '&' +
249:             'state_url=' + encodeURIComponent(window.location.hash);
250:         if (this.params.hasOwnProperty('nonce')) {
251:             url += '&nonce=' + encodeURIComponent(this.params.nonce);
252:         }
253:         url += '&state=' + encodeURIComponent(this.params.state);
254:         window.location.replace(url);
255:         return url;
256:     }
