275:     autologout(expires: any): void {
276:         if (expires) {
277:             this.isLogin = true;
278:             const expiresIn = ((new Date(expires)).getTime() - (new Date()).getTime());
279:             if (expiresIn < this.timeLogoutBefore) {
280:                 this.clearStorage();
281:                 this.logoutSubject.next('logout-auto-only-localstorage');
282:                 location.reload();
283:             } else {
284:                 const timerDelay = expiresIn > this.timeLogoutBefore ? expiresIn - this.timeLogoutBefore : this.timeLogoutBefore;
285:                 if (!isNaN(expiresIn)) {
286:                     console.log(`%cFecha expiración: %c${new Date(expires)}`, 'color: blue', 'color: green');
287:                     of(null).pipe(delay(timerDelay - this.timeLogoutBefore)).subscribe((data) => {
288:                         this.logout('logout-auto');
289:                     });
290:                     if (this.timeAlert < timerDelay) {
291:                         of(null).pipe(delay(timerDelay - this.timeAlert)).subscribe((data) => {
292:                             Swal.fire({
293:                                 position: 'top-end',
294:                                 icon: 'info',
295:                                 title: `Su sesión se cerrará en ${this.timeAlert / 60000} minutos`,
296:                                 showConfirmButton: false,
297:                                 timer: this.timeActiveAlert
298:                             });
299:                         });
300:                     }
301:                 }
302:             }
303:         }
304:     }
305:     public expired() {
306:         return (new Date(window.localStorage.getItem('expires_at')!) < new Date());
307:     }
308: 
309:     public live() {
310:         return this.isLogin;
311:     }
312: 
313:     public clearStorage() {
314:         this.isLogin = false;
315:         window.localStorage.clear();
316:         window.sessionStorage.clear();
317:     }
