553:   private applyFilters(): void {
554:     this.filteredSabaticos = this.historialEstadoSabaticos.filter((historial) => {
555:       const matchesId = this.matchesFilter(historial.id, this.columnFilters.id);
556:       const matchesFechaInicio = this.matchesDate(historial.fechaInicio, this.columnFilters.fechaInicio);
557:       const matchesFechaFinal = this.matchesDate(historial.fechaFinal, this.columnFilters.fechaFinal);
558:       const matchesEstado = this.matchesFilter(historial.estadoSabatico, this.columnFilters.estadoSabatico);
559:       const matchDocenteNombre = this.matchesFilter(historial.docenteNombre, this.columnFilters.docenteNombre)
560: 
561:       return matchesId && matchesFechaInicio && matchesFechaFinal && matchesEstado && matchDocenteNombre;
562:     });
