573:     private mapHistorialResponse(data: any[]): HistorialEstadoSabaticos[] {
574:     return data.map((item) => {
575:       const fechaInicio =  this.formatApiDate(item.SabaticoId?.FechaInicio ) ?? '';
576:       const fechaFinal = this.formatApiDate(item.SabaticoId?.FechaFin) ?? '';
577:       const terceroId = Number(
578:         item.TerceroId?.Id ??
579:         item.TerceroId ??
580:         item.SabaticoId?.TerceroId?.Id ??
581:         item.SabaticoId?.TerceroId
582:       );
583:   
584:       return {
585:         id: String(item.SabaticoId?.Id ?? item.Id ?? ''),
586:         fechaInicio: this.formatApiDate(item.SabaticoId?.FechaInicio ) ?? '',
587:         fechaFinal: this.formatApiDate(item.SabaticoId?.FechaFin) ?? '',
588:         estadoSabatico: item.EstadoSabaticoId?.NombreEstado,
589:         estadoSabaticoCodigo: item.EstadoSabaticoId?.CodigoAbreviacion,
590:         docenteNombre: item.Tercero?.NombreCompleto ?? item.TerceroId?.NombreCompleto ?? '',
591:         ...(Number.isFinite(terceroId) && terceroId > 0 ? { terceroIdDocente: terceroId } : {})
592:       };
593:     });
594:   }
