596:   private fetchDocenteInfoForSabaticos(sabaticos: HistorialEstadoSabaticos[]): void {
597:     const terceroIds = [...new Set(
598:       sabaticos
599:         .filter((item) => !item.docenteNombre)
600:         .map((item) => item.terceroIdDocente)
601:         .filter((id): id is number => Boolean(id && id > 0))
602:     )];
603: 
604:     terceroIds.forEach((terceroId) => {
605:       this.tercerosService.get(`tercero/${terceroId}`)
606:         .pipe(takeUntilDestroyed(this.destroyRef))
607:         .subscribe({
608:           next: (response: any) => {
609:             const nombre = response?.NombreCompleto ?? '';
610:             if (!nombre) {
611:               return;
612:             }
613: 
614:             this.historialEstadoSabaticos.forEach((item) => {
615:               if (item.terceroIdDocente === terceroId) {
616:                 item.docenteNombre = nombre;
617:               }
618:             });
619:             this.applyFilters();
620:           },
621:           error: () => {}
622:         });
623:     });
624:   }
