626:     private formatApiDate(fechaRaw: string): string {
627:     if (!fechaRaw) return '';
628:     const dateObj = new Date(fechaRaw);
629:     if (Number.isNaN(dateObj.getTime())) {
630:       const match = fechaRaw.match(/^(\d{4}-\d{2}-\d{2})/);
631:       return match ? match[1] : '';
632:     }
633:     return this.formatLocalDate(dateObj);
634:   }
635: 
636:     private formatLocalDate(date: Date): string {
637:     const year = date.getFullYear();
638:     const month = String(date.getMonth() + 1).padStart(2, '0');
639:     const day = String(date.getDate()).padStart(2, '0');
640:     return `${year}-${month}-${day}`;
641:   }
642: 
643:   private parseLocalDate(value: string): Date | null {
644:     if (!value) {
645:       return null;
646:     }
647: 
648:     const [year, month, day] = value.split('-').map(Number);
649:     if (!year || !month || !day) {
650:       return null;
651:     }
652: 
653:     const parsed = new Date(year, month - 1, day);
654:     return Number.isNaN(parsed.getTime()) ? null : parsed;
655:   }
656: 
657:   private matchesDate(value: string, filterValue: string): boolean {
658:   if (!filterValue) return true;
659:   return value === filterValue;
660: }
661: 
662: formatDate(date: Date | null): string {
663:   if (!date) return '';
664:   return this.formatLocalDate(date);
665: }
666: 
667:   private normalize(value: string): string {
668:     return value
669:       ? value
670:         .normalize('NFD')
671:         .replace(/\p{Diacritic}/gu, '')
672:         .toLowerCase()
673:       : '';
674:   }
675: }

